{
  "candidates": [
    {
      "explanation": "Moderate pipeline-aware boost for all nodes when demand growth is high, with extra boost for upstream nodes to prevent starvation. Downstream nodes get smaller boost to avoid over-ordering.",
      "rules": [
        {
          "when": "growth > 1.2 and backlog > 0",
          "delta": "min(6, max(0, 2 + (growth - 1.2) * 4))"
        },
        {
          "when": "growth > 1.2 and backlog == 0 and inventory < 5",
          "delta": "min(4, max(0, 1 + (growth - 1.2) * 3))"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Aggressive boost for upstream nodes (agent 2) to ensure supply, moderate for middle, and conservative for downstream to avoid excess backlog. Uses pipeline coverage to avoid over-ordering when pipeline is already large.",
      "rules": [
        {
          "when": "agent == 2 and growth > 1.1 and backlog > 0",
          "delta": "min(6, max(0, 3 + (growth - 1.1) * 5))"
        },
        {
          "when": "agent == 1 and growth > 1.1 and backlog > 0",
          "delta": "min(4, max(0, 2 + (growth - 1.1) * 3))"
        },
        {
          "when": "agent == 0 and growth > 1.1 and backlog > 0",
          "delta": "min(2, max(0, 1 + (growth - 1.1) * 2))"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, but boost when backlog is high and pipeline is low. Coordinated across nodes.",
      "rules": [
        {
          "when": "backlog > 0 and pipeline < recent * 2",
          "delta": "min(6, max(0, 2 + (recent - pipeline/2) * 0.5))"
        },
        {
          "when": "pipeline > recent * 3 and backlog == 0",
          "delta": "max(-6, min(0, -1 * (pipeline - recent * 3) * 0.2))"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to backlog to avoid over-ordering and future inventory, but increase orders when backlog is high and pipeline is low to recover service. Coordinated across nodes.",
      "rules": [
        {
          "when": "backlog > 0 and pipeline < backlog * 2",
          "delta": "min(6, max(2, backlog / 10))"
        },
        {
          "when": "pipeline > backlog * 3",
          "delta": "-min(6, max(1, pipeline / 20))"
        },
        {
          "when": "inventory > 0 and backlog == 0",
          "delta": "-min(6, max(1, inventory / 10))"
        }
      ]
    },
    {
      "explanation": "Demand-emergency response: boost orders when recent demand growth is high and backlog exists, but cap increases to avoid upstream backlog. Reduce orders when pipeline is excessive relative to backlog.",
      "rules": [
        {
          "when": "growth > 1.2 and backlog > 0",
          "delta": "min(6, max(2, backlog / 8))"
        },
        {
          "when": "pipeline > backlog * 2.5",
          "delta": "-min(6, max(1, pipeline / 15))"
        },
        {
          "when": "inventory > 0 and backlog == 0",
          "delta": "-min(6, max(1, inventory / 12))"
        }
      ]
    },
    {
      "explanation": "Balanced correction: increase orders moderately when backlog is high and pipeline is not too large, decrease when pipeline is large relative to backlog, and reduce when inventory is positive without backlog.",
      "rules": [
        {
          "when": "backlog > 0 and pipeline < backlog * 3",
          "delta": "min(6, max(1, backlog / 12))"
        },
        {
          "when": "pipeline > backlog * 4",
          "delta": "-min(6, max(1, pipeline / 25))"
        },
        {
          "when": "inventory > 0 and backlog == 0",
          "delta": "-min(6, max(1, inventory / 15))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Modest coordinated increase to all nodes to rebuild inventory and reduce backlog during demand surge, with slightly larger increase at node0 to address severe backlog.",
      "rules": [
        {"when": "agent==0", "delta": "min(3, max(0, (recent-baseline)*0.5))"},
        {"when": "agent==1", "delta": "min(2, max(0, (recent-baseline)*0.3))"},
        {"when": "agent==2", "delta": "min(2, max(0, (recent-baseline)*0.3))"}
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand to avoid over-ordering and upstream backlog, while still increasing if backlog is high.",
      "rules": [
        {"when": "agent==0", "delta": "min(3, max(-2, (backlog - pipeline/4)*0.1))"},
        {"when": "agent==1", "delta": "min(2, max(-2, (backlog - pipeline/4)*0.1))"},
        {"when": "agent==2", "delta": "min(2, max(-2, (backlog - pipeline/4)*0.1))"}
      ]
    },
    {
      "explanation": "Growth-based adjustment: increase orders proportionally to demand growth, but cap increases to avoid overshoot, and reduce if growth is low.",
      "rules": [
        {"when": "agent==0", "delta": "min(4, max(-2, (growth-1)*10))"},
        {"when": "agent==1", "delta": "min(3, max(-2, (growth-1)*8))"},
        {"when": "agent==2", "delta": "min(3, max(-2, (growth-1)*8))"}
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Moderate boost to upstream orders to rebuild pipeline and reduce backlog, with small downstream boost to prevent starvation. Node0 increases order to cover backlog and pipeline deficit; node1 increases to cover backlog and pipeline; node2 increases to build inventory ahead of demand.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, max(0, backlog/5 + (recent - pipeline/4)/2))"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(6, max(0, backlog/3 + (recent - pipeline/4)/2))"
        },
        {
          "when": "agent==2 and inventory<recent*2",
          "delta": "min(6, max(0, (recent*2 - inventory)/4))"
        }
      ]
    },
    {
      "explanation": "Aggressive upstream boost to quickly clear backlog and rebuild pipeline, with downstream orders kept high to avoid stockouts. Node0 and node1 increase orders significantly when backlog exists; node2 increases to maintain safety stock.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, max(0, backlog/3 + (recent - pipeline/4)))"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(6, max(0, backlog/2 + (recent - pipeline/4)))"
        },
        {
          "when": "agent==2 and inventory<recent*3",
          "delta": "min(6, max(0, (recent*3 - inventory)/3))"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand to avoid overstock, but increase when backlog is high. Node0 and node1 reduce if pipeline exceeds recent demand; node2 reduces if inventory is high.",
      "rules": [
        {
          "when": "agent==0 and pipeline > recent*4",
          "delta": "max(-6, min(0, (recent*4 - pipeline)/4))"
        },
        {
          "when": "agent==1 and pipeline > recent*4",
          "delta": "max(-6, min(0, (recent*4 - pipeline)/4))"
        },
        {
          "when": "agent==2 and inventory > recent*2",
          "delta": "max(-6, min(0, (recent*2 - inventory)/4))"
        },
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, max(0, backlog/4))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Refines the best prior candidate (llm_r0_2) by slightly increasing the backlog-driven boost and making the pipeline-based reduction more responsive. The rules coordinate across nodes: when backlog exists and pipeline is not excessive, orders are increased to recover service; when pipeline is very high relative to backlog, orders are reduced to avoid over-ordering; and when inventory is positive with no backlog, orders are reduced to prevent excess inventory.",
      "rules": [
        {
          "when": "backlog > 0 and pipeline < backlog * 3",
          "delta": "min(6, max(1, backlog / 10))"
        },
        {
          "when": "pipeline > backlog * 4",
          "delta": "-min(6, max(1, pipeline / 20))"
        },
        {
          "when": "inventory > 0 and backlog == 0",
          "delta": "-min(6, max(1, inventory / 15))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Refinement of llm_r0_0: node0 increases order when backlog is high relative to pipeline, capped at +4; nodes1 and2 increase modestly only when their backlog is high relative to pipeline, capped at +2. This targets downstream service without causing upstream backlog.",
      "rules": [
        {
          "when": "agent==0",
          "delta": "min(4, max(0, (backlog - pipeline/4)*0.2))"
        },
        {
          "when": "agent==1",
          "delta": "min(2, max(0, (backlog - pipeline/4)*0.2))"
        },
        {
          "when": "agent==2",
          "delta": "min(2, max(0, (backlog - pipeline/4)*0.2))"
        }
      ]
    }
  ]
}

